element.style.position = 'relative';

if (element.querySelector('.category-tags-bar')) return;

const bar = document.createElement('div');
bar.className = 'category-tags-bar';
bar.style.cssText = 'display:flex;flex-wrap:wrap;gap:8px;margin-top:12px;margin-bottom:4px;';

const categories = [
  { label: 'Space', href: 'https://weather.com/news/space' },
  { label: 'Astronomy', href: 'https://weather.com/news/astronomy' },
  { label: 'Exoplanets', href: 'https://weather.com/news/exoplanets' },
  { label: 'NASA', href: 'https://weather.com/news/nasa' },
  { label: 'Hubble Telescope', href: 'https://weather.com/news/hubble-telescope' }
];

categories.forEach(function(cat) {
  const a = document.createElement('a');
  a.href = cat.href;
  a.textContent = cat.label;
  a.target = '_blank';
  a.rel = 'noopener noreferrer';
  a.style.cssText = 'display:inline-block;padding:4px 12px;font-size:13px;font-weight:700;color:#ffffff;background-color:#003399;border-radius:9999px;text-decoration:none;transition:background-color 0.2s,opacity 0.2s;white-space:nowrap;line-height:1.4;';
  a.onmouseover = function() { this.style.backgroundColor = '#0050d4'; };
  a.onmouseout = function() { this.style.backgroundColor = '#003399'; };
  bar.appendChild(a);
});

element.parentNode.insertBefore(bar, element.nextSibling);
